INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 2, 1, 1, -416.5, 1, 0, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "2025/01/31 12:00:00", 3.414, 62, 1000001, 190801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 2, 1, 2, -416.5, 1, 0, "ミッションをクリアして、\n報酬をゲットしましょう！", "2025/01/31 12:00:00", 3.099, 62, 1000002, 190801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 2, 1, 3, -416.5, 1, 0, "受け取ることができる\n報酬があるようです\n確認してみてください", "2025/01/31 12:00:00", 2.801, 63, 1000003, 190801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 2, 2, 4, -416.5, 1, 0, "報酬がもらえますよ！\nチェックしてみてください", "2025/01/31 12:00:00", 0, 63, 1000004, 190801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 1, 2, 5, -363, 1, 0, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "2025/01/31 12:00:00", 2.12, 64, 1000005, 190801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 2, 1, 6, -363, 1, 0, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "2025/01/31 12:00:00", 1.68, 64, 1000006, 190801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 1, 2, 7, -363, 1, 0, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "2025/01/31 12:00:00", 2.33, 64, 1000007, 190801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ラビリスタ", 7, 3, 101, -285, 10201, -6, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", "2025/01/31 12:00:00", 5.18, 61, 1020101, 133701);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "クリスティーナ", 2, 1, 201, -285, 10201, -2, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", "2025/01/31 12:00:00", 8.77, 61, 1020102, 133901);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ネネカ", 1, 6, 301, -285, 10201, 0, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", "2025/01/31 12:00:00", 15.5, 61, 1020103, 133801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ランファ", 5, 2, 101, -285, 10202, 0, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", "2025/02/28 12:00:00", 9.061, 61, 1020201, 134301);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "チカ", 2, 1, 201, -285, 10202, 0, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", "2025/02/28 12:00:00", 7.699, 61, 1020202, 134401);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "アオイ", 2, 1, 101, -285, 10203, 0, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", "2025/03/31 12:00:00", 8.595, 61, 1020301, 134601);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "クローチェ", 2, 1, 201, -285, 10203, 0, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", "2025/03/31 12:00:00", 7.758, 61, 1020302, 134501);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ルイズマリー", 6, 2, 101, -285, 10204, 0, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", "2025/04/30 12:00:00", 7, 61, 1020401, 132302);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "イロハ", 2, 1, 201, -285, 10204, 0, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", "2025/04/30 12:00:00", 7.904, 61, 1020402, 132402);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ソノ", 2, 4, 301, -285, 10204, 0, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", "2025/04/30 12:00:00", 8.487, 61, 1020403, 132502);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カノン", 2, 1, 101, -285, 10205, 0, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", "2025/05/31 12:00:00", 8.763, 61, 1020502, 134901);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ツムギ", 3, 1, 201, -285, 10205, 0, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", "2025/05/31 12:00:00", 6.417, 61, 1020503, 134801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "エリス", 7, 3, 101, -285, 10206, 0, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", "2025/06/30 12:00:00", 10.335, 61, 1020601, 135001);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "シェフィ", 4, 2, 201, -285, 10206, 0, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", "2025/06/30 12:00:00", 6.281, 61, 1020602, 135101);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "プレシア", 2, 1, 301, -285, 10206, 0, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", "2025/06/30 12:00:00", 12.244, 61, 1020603, 135201);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "クリア", 8, 2, 101, -285, 10207, 0, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", "2025/07/31 12:00:00", 6.339, 61, 1020701, 135301);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "アネモネ", 9, 7, 201, -285, 10207, 0, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", "2025/07/31 12:00:00", 8.184, 61, 1020702, 135401);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "アイラ", 2, 9, 101, -285, 10208, 0, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", "2025/08/31 12:00:00", 3.906, 61, 1020801, 129101);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "シナツ", 2, 1, 201, -285, 10208, 0, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", "2025/08/31 12:00:00", 14.465, 61, 1020802, 129201);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ヒヨリ", 3, 4, 301, -285, 10208, 0, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", "2025/08/31 12:00:00", 8.662, 61, 1020803, 100101);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "レイ", 3, 1, 401, -285, 10208, 0, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", "2025/08/31 12:00:00", 10.915, 61, 1020804, 100301);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ユキノ", 7, 1, 101, -285, 10209, 0, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", "2025/09/30 12:00:00", 6.042, 61, 1020901, 135802);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "サツキ", 1, 4, 201, -285, 10209, 0, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", "2025/09/30 12:00:00", 9.402, 61, 1020902, 135903);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ルルィ", 1, 8, 301, -285, 10209, 0, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", "2025/09/30 12:00:00", 8.16, 61, 1020903, 136902);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カスミ", 2, 3, 101, -285, 10210, 0, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", "2025/10/31 12:00:00", 5, 61, 1021001, 137401);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "アラクネ", 1, 4, 201, -285, 10210, 0, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", "2025/10/31 12:00:00", 8.12, 61, 1021002, 136001);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ナーナ", 2, 4, 301, -285, 10210, 0, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", "2025/10/31 12:00:00", 6.386, 61, 1021003, 136202);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ユイ", 4, 3, 101, -285, 10211, 0, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", "2025/11/30 12:00:00", 7.438, 61, 1021101, 136402);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ミソラ", 5, 1, 201, -285, 10211, 0, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", "2025/11/30 12:00:00", 8.35, 61, 1021102, 136302);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "シズル", 2, 1, 101, -285, 10212, 0, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", "2025/12/31 12:00:00", 5, 61, 1021201, 136501);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "リノ", 2, 1, 201, -285, 10212, 0, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", "2025/12/31 12:00:00", 5.25, 61, 1021202, 137902);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ラビリスタ", 2, 1, 301, -285, 10212, 0, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", "2025/12/31 12:00:00", 7.5, 61, 1021203, 106801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ライラエル", 2, 1, 101, -285, 10213, 0, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", "2026/01/31 12:00:00", 8.204, 61, 1021301, 126501);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ネフィ＝ネラ", 2, 1, 201, -285, 10213, 0, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", "2026/01/31 12:00:00", 7.176, 61, 1021302, 129701);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ヴァイオレット", 5, 1, 301, -285, 10213, 0, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", "2026/01/31 12:00:00", 8.602, 61, 1021303, 133101);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ライラエル", 3, 1, 102, -285, 10213, 0, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", "2026/02/06 12:00:00", 10.14, 61, 1021304, 138101);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ネフィ＝ネラ", 7, 1, 202, -285, 10213, 0, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", "2026/02/06 12:00:00", 10.152, 61, 1021305, 138201);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ヴァイオレット", 3, 4, 302, -285, 10213, 0, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", "2026/02/06 12:00:00", 9.688, 61, 1021306, 138001);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ペコリーヌ", 1, 2, 401, -285, 10213, 0, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", "2026/02/12 12:00:00", 5.928, 61, 1021307, 138301);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ワカナ", 2, 4, 101, -285, 10214, 0, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", "2026/02/28 12:00:00", 9.19, 61, 1021401, 138702);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "シオリ", 3, 1, 201, -285, 10214, 0, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", "2026/02/28 12:00:00", 8.724, 61, 1021402, 138802);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "グレイス", 1, 4, 101, -285, 10215, 0, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", "2026/03/31 12:00:00", 7.758, 61, 1021501, 138902);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "キョウカ", 4, 6, 201, -285, 10215, 0, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", "2026/03/31 12:00:00", 6.375, 61, 1021502, 139002);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ルルィ", 1, 6, 301, -285, 10215, 0, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", "2026/03/31 12:00:00", 6.173, 61, 1021503, 136902);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ミホ", 2, 6, 101, -285, 10216, 0, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", "2026/04/30 12:00:00", 4.202, 61, 1021601, 139202);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "マホ", 1, 6, 201, -285, 10216, 0, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", "2026/04/30 12:00:00", 2.842, 61, 1021602, 139302);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "エリカ", 1, 4, 301, -285, 10216, 0, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", "2026/04/30 12:00:00", 4.598, 61, 1021603, 139402);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "リリ", 3, 4, 101, -285, 10217, 0, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", "2026/05/31 12:00:00", 6.533, 61, 1021701, 125802);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "プレシア", 3, 3, 301, -285, 10217, 0, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", "2026/05/31 12:00:00", 5, 61, 1021702, 126102);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "クリア", 4, 3, 201, -285, 10217, 0, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", "2026/05/31 12:00:00", 5.214, 61, 1021703, 126002);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "リリ", 3, 1, 102, -285, 10217, 0, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", "2026/05/31 12:00:00", 8.781, 61, 1021704, 139501);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "クリア", 1, 2, 202, -285, 10217, 0, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", "2026/05/31 12:00:00", 6.529, 61, 1021705, 139601);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "プレシア", 2, 3, 302, -285, 10217, 0, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", "2026/05/31 12:00:00", 3.195, 61, 1021706, 139701);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ルイズマリー", 3, 2, 101, -285, 10218, 0, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", "2026/06/30 12:00:00", 12.43, 61, 1021801, 139902);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "クレジッタ", 3, 2, 201, -285, 10218, 0, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", "2026/06/30 12:00:00", 6.35, 61, 1021802, 140001);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "フブキ", 5, 1, 101, -285, 10219, 0, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", "2026/07/31 12:00:00", 10.23, 61, 1021901, 140102);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ヴァンピィ", 2, 1, 201, -285, 10219, 0, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", "2026/07/31 12:00:00", 5.584, 61, 1021902, 140201);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "クローチェ", 3, 6, 201, -285, 10220, 0, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", "2026/08/31 12:00:00", 2.8, 61, 1022001, 126401);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ヴルム", 3, 4, 101, -285, 10220, 0, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", "2026/08/31 12:00:00", 8.9, 61, 1022002, 127802);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "クローチェ", 1, 2, 202, -285, 10220, 0, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", "2026/08/31 12:00:00", 4.49, 61, 1022003, 140602);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ヴルム", 3, 1, 102, -285, 10220, 0, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", "2026/08/31 12:00:00", 9.42, 61, 1022004, 140501);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "リーザ", 1, 4, 301, -285, 10220, 0, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", "2026/08/31 12:00:00", 7, 61, 1022005, 140402);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "アーモンドアイ", 3, 1, 101, -285, 10221, 0, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", "2026/10/31 12:00:00", 8.61, 61, 1022101, 141101);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ラッキーライラック", 1, 6, 201, -285, 10221, 0, "ゴルシさんは相変わらずやねぇ…\nまぁせっかくの異世界やし\nいつもと違うレース、\n楽しませてもらいましょ", "2026/10/31 12:00:00", 3.55, 61, 1022102, 141201);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "デアリングタクト", 1, 2, 301, -285, 10221, 0, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", "2026/10/31 12:00:00", 8.26, 61, 1022103, 141301);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ゴールドシップ", 1, 2, 401, -285, 10221, 0, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", "2026/10/31 12:00:00", 8.79, 61, 1022104, 141001);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "アーモンドアイ", 3, 1, 101, -285, 10221, 0, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", "2026/10/31 12:00:00", 8.61, 61, 1022105, 141101);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ラッキーライラック", 2, 1, 202, -285, 10221, 0, "（剣と魔法！　ええなぁ～！\nうちも魔法覚えられるやろか\nレースの後に花咲かせたり…\nくぅ～っ！　はよ試したいわ！）", "2026/10/31 12:00:00", 2.69, 61, 1022106, 141201);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "デアリングタクト", 1, 2, 301, -285, 10221, 0, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", "2026/10/31 12:00:00", 8.26, 61, 1022107, 141301);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "ゴールドシップ", 1, 2, 401, -285, 10221, 0, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", "2026/10/31 12:00:00", 8.79, 61, 1022108, 141001);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 2, 1, 1, -416.5, 2, 0, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "2026/04/10 12:00:00", 3.414, 62, 2000001, 190801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 2, 1, 2, -416.5, 2, 0, "ミッションをクリアして、\n報酬をゲットしましょう！", "2026/04/10 12:00:00", 3.099, 62, 2000002, 190801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 2, 1, 3, -416.5, 2, 0, "受け取ることができる\n報酬があるようです\n確認してみてください", "2026/04/10 12:00:00", 2.801, 63, 2000003, 190801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 2, 2, 4, -416.5, 2, 0, "報酬がもらえますよ！\nチェックしてみてください", "2026/04/10 12:00:00", 0, 63, 2000004, 190801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 1, 2, 5, -363, 2, 0, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "2026/04/10 12:00:00", 2.12, 64, 2000005, 190801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 2, 1, 6, -363, 2, 0, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "2026/04/10 12:00:00", 1.68, 64, 2000006, 190801);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", "カリン", 1, 2, 7, -363, 2, 0, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "2026/04/10 12:00:00", 2.33, 64, 2000007, 190801);
